package com.vaijunto.controller;
import com.vaijunto.dto.*; import com.vaijunto.service.MediaStorageService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/media") @RequiredArgsConstructor public class MediaController {private final MediaStorageService service; @PostMapping("/upload-intents") public MediaUploadIntentDto intent(@Valid @RequestBody MediaUploadIntentRequest request,Authentication auth){return service.intent(request,auth.getName());}@PostMapping("/{id}/complete") public void complete(@PathVariable UUID id,Authentication auth){service.complete(id,auth.getName());}@GetMapping("/{id}/download-url") public Map<String,String> url(@PathVariable UUID id,Authentication auth){return Map.of("url",service.downloadUrl(id,auth.getName()));}}
